import numpy as np
from collections import defaultdict

# --- Minimal Mock Classes for the Test ---
class MockAgent:
    def __init__(self, agent_id):
        self.agent_id = agent_id
        self.total_reward = 0
        self.current_resources = {}

    def choose_action(self, *args, **kwargs):
        # Action doesn't matter for this test
        return ("gather", "wood")

    def update_learning(self, chosen_action, collective_round_reward, **kwargs):
        # This is the line under investigation
        self.total_reward += collective_round_reward

    def record_actions(self, *args, **kwargs): pass
    def calculate_specialization_index(self, *args, **kwargs): pass
    def update_reputation_from_round_outcome(self, *args, **kwargs): pass
    def consider_strategy_adoption(self, *args, **kwargs): pass

class MockEnvironment:
    def __init__(self):
        self.building_status = {"part1": self} # Mock object for checks
        self.assembled = False
        self.world_resources = {"wood": self}
        self.amount = 100
        self.world_components = {}

    def process_actions(self, agent_actions, agents_dict):
        # Return a fixed reward for simplicity
        return 10.0

    def get_all_possible_action_keys(self):
        return []

# --- Unit Test ---
print("--- Unit Test 2: Reward Accumulation Logic ---")
agents = {'agent_1': MockAgent('agent_1'), 'agent_2': MockAgent('agent_2')}
env = MockEnvironment()

NUM_ROUNDS_TEST = 3
for i in range(NUM_ROUNDS_TEST):
    print(f"\n--- Round {i+1} ---")
    agent_actions = {aid: agent.choose_action() for aid, agent in agents.items()}

    # The environment calculates a single reward for the round
    collective_round_reward = env.process_actions(agent_actions, agents)
    print(f"Collective Reward for Round: {collective_round_reward}")

    # Each agent updates their internal state based on that single reward
    for agent_id, agent in agents.items():
        agent.update_learning(agent_actions[agent_id], collective_round_reward)

    # Print the results for this round
    for agent_id, agent in agents.items():
        print(f"  {agent_id} total_reward: {agent.total_reward}")

print("\n--- Final State ---")
final_sum = sum(a.total_reward for a in agents.values())
print(f"Final sum of agent rewards: {final_sum}")

# For 3 rounds, the total reward given by env is 3*10 = 30.
# The final sum should be 30 * num_agents = 30 * 2 = 60.
expected_final_sum = NUM_ROUNDS_TEST * 10.0 * len(agents)
print(f"Expected final sum (Rounds * Reward * NumAgents): {expected_final_sum}")

if final_sum == expected_final_sum:
    print("\nVERDICT: BUG CONFIRMED. The total reward is being multiplied by the number of agents.")
else:
    print("\nVERDICT: TEST INCONCLUSIVE or bug is elsewhere.")
